command:
// ==========================================
// ⚙️ LUNAS WIRKUNG: BLUTHEILUNG (BRONA)
//
// - Reichweite: selbst
// - Ziel: ausschließlich der Wirkender
// - KEIN Target erforderlich, KEIN GM-Zwischenschritt
// - Heilung: 2W6 + aufgerundete QS/2 (niemals über LeP-Maximum)
// - Nutzt Block 19.8 für eine systemkonforme Chatkarte
// - Kompakte Anzeige ohne Meta-Zahlen (kein Vorher-Nachher)
// ==========================================

(async function () {
    const macroUuid = this?.uuid || null;

    // +++ 1 - FRAMEWORK LADEN +++++++++++++++++++++++++++++++++
    const frameworkUuid = "Compendium.dsk-havena-und-umland.makros.Macro.fHQ2OuDo3Fe3spBn";

    if (typeof DSK === "undefined" || !globalThis.DSK) {
        const fwMacro = await fromUuid(frameworkUuid);
        if (fwMacro) await fwMacro.execute();
        await new Promise(resolve => setTimeout(resolve, 150));
    }

    if (typeof DSK === "undefined" && !globalThis.DSK) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework konnte nicht geladen werden!");
    }

    const DSK_FW = globalThis.DSK || DSK;

    if (!DSK_FW?.QS || !DSK_FW?.Token || !DSK_FW?.GabenUI) {
        return ui.notifications.error("Luna sagt 🌙: Das DSK-Framework wurde nicht vollständig geladen!");
    }

    // +++ 2 - GRUNDDATEN ++++++++++++++++++++++++++++++++++++++
    const gabenName = "Blutheilung";
    const ahne = "Brona";
    const vollerName = `${gabenName} (${ahne})`;
    const symbolPfad = DSK_FW.Symbol(ahne);

    // +++ 3 - WIRKENDEN ERMITTELN +++++++++++++++++++++++++++++
    let casterActor = canvas.tokens.controlled[0]?.actor || game.user.character || null;

    if (!casterActor) {
        casterActor = canvas.tokens.placeables.map(token => token.actor)
            .find(actor => actor?.getFlag("world", "letzteGabenQS") !== undefined) ||
            game.actors.find(actor => actor.getFlag("world", "letzteGabenQS") !== undefined) || null;
    }

    if (!casterActor) return ui.notifications.warn("Luna sagt 🌙: Kein Wirkender gefunden! Bitte wähle den Token des Wirkenden aus.");

    const casterToken = DSK_FW.Token.Finde(casterActor);
    if (!casterToken) return ui.notifications.warn("Luna sagt 🌙: Das Token des Wirkenden wurde nicht gefunden!");

    const casterName = DSK_FW.ResolveTokenName(casterActor);

    // +++ 4 - QS ERMITTELN ++++++++++++++++++++++++++++++++++++
    const qs = DSK_FW.QS.Ermitteln({
        actor: casterActor,
        gabenName,
        suchbegriffe: ["Blutheilung Probe", "Blutheilung"],
        testDataObj: typeof testData !== "undefined" ? testData : null,
        fallback: 0,
        protokollieren: true
    });

    if (qs <= 0) {
        return ui.notifications.warn("Luna sagt 🌙: Die Probe ist fehlgeschlagen oder die Qualitätsstufe konnte nicht ermittelt werden!");
    }

    // +++ 5 - LEP DES WIRKENDEN ERMITTELN +++++++++++++++++++++
    const aktuelleLeP = Number(casterActor.system?.stats?.LeP?.value) || 0;
    const maxLeP = Number(casterActor.system?.stats?.LeP?.max) || 0;

    if (maxLeP <= 0) {
        return ui.notifications.error("Luna sagt 🌙: Die maximalen LeP des Wirkenden konnten nicht ermittelt werden!");
    }

    // +++ 6 - HEILUNG WÜRFELN (2W6 + aufgerundete QS/2) +++++++
    const bonus = Math.ceil(qs / 2);
    const healRoll = await new Roll(`2d6 + ${bonus}`).evaluate({ async: true });

    const gewuerfelteHeilung = Number(healRoll.total) || 0;
    const wuerfelErgebnisse = healRoll.dice?.[0]?.results?.map(result => result.result).join(" + ") || "?";

    // +++ 7 - HEILUNG BERECHNEN UND ANWENDEN ++++++++++++++++++
    let neueLeP = aktuelleLeP;
    let tatsaechlicheHeilung = 0;
    let bereitsVoll = false;

    if (aktuelleLeP >= maxLeP) {
        bereitsVoll = true;
    } else {
        neueLeP = Math.min(maxLeP, aktuelleLeP + gewuerfelteHeilung);
        tatsaechlicheHeilung = Math.max(0, neueLeP - aktuelleLeP);

        await casterActor.update({
            "system.stats.LeP.value": neueLeP
        });
    }

    // +++ 8 - CHATKARTE VORBEREITEN (BLOCK 19.8) ++++++++++++++
    const basisBeschreibung = 
        `Der Vampir wandelt gesaugtes Blut in Lebensenergie um.` +
        `<br><br><b>Reichweite:</b> selbst` +
        `<br><b>Ziel:</b> Wirkender` +
        `<br><b>Heilung:</b> 2W6 + aufgerundete QS/2` +
        `<br><b>Maximum:</b> Die LeP können das persönliche Maximum nicht überschreiten.` +
        `<br><hr>` +
        `<div style="text-align:center; padding:6px; background:rgba(0,0,0,0.03); border:1px solid #c9bca6; border-radius:4px; margin-bottom:4px;">` +
            `<span style="font-size:0.9em; color:#555;">Gewürfelte Heilung:</span><br>` +
            `<b style="color:#76301b; font-size:1.2em;">${gewuerfelteHeilung} LeP</b><br>` +
            `<span style="font-weight:300; font-size:0.9em; opacity:0.8;">Würfel: [${wuerfelErgebnisse}] + Bonus: ${bonus}<br>(bei QS ${qs})</span>` +
        `</div>`;

    const rolleErgebnis = bereitsVoll 
        ? `<span style="color:#B30000;">Keine Heilung notwendig</span>` 
        : `<span style="color:#18940F; font-weight:bold;">+${tatsaechlicheHeilung} LeP</span>`;

    // +++ 9 - ÖFFENTLICHE CHATKARTE ERZEUGEN ++++++++++++++++++
    await DSK_FW.GabenUI.AnfrageKarteErstellen({
        gabenName: vollerName,
        ahne,
        beschreibung: basisBeschreibung,
        wirkender: casterName,
        ziele: [{ name: casterName, rolle: rolleErgebnis }],
        misserfolge: [],
        dauerText: "Augenblicklich",
        gmBereich: false,
        angewendet: true,
        erfolgreich: true,
        anfragenderUserId: game.user.id
    });

    // +++ 10 - FLAGS AUFRÄUMEN ++++++++++++++++++++++++++++++++
    if (casterActor.getFlag("world", "letzteGabenQS") !== undefined) {
        await casterActor.unsetFlag("world", "letzteGabenQS");
    }
    if (casterActor.getFlag("world", "letzteGabenMessageId") !== undefined) {
        await casterActor.unsetFlag("world", "letzteGabenMessageId");
    }

}).call(this);
